        private static readonly System.Collections.Generic.Dictionary<(short, short), string> Chunks = new System.Collections.Generic.Dictionary<(short, short), string> {
            { ((short)1, (short)0), "BE IT KNOWN THAT THE\rCOUNCIL IS INTERESTED IN\rRECLAIMING THE REMAINING\rBLOCKS OF THE CITY OF NEW\rPHLAN. TO RECLAIM SAID\rBLOCKS THEY MUST BE FIRST\rCLEARED OF MONSTERS,\rVERMIN, AND OTHER\rUNCIVILIZED INHABITANTS. TO" },
            { ((short)1, (short)1), "THIS END THE COUNCIL IS\rOFFERING A REWARD TO ANY\rPERSON OR GROUP WHO IS\rRESPONSIBLE FOR CLEARING\rANY BLOCK OF THE OLD CITY." },
            { ((short)2, (short)0), "BE IT KNOWN THAT THE\rCOUNCIL IS INTERESTED IN\rACQUIRING INFORMATION AS TO\rTHE DISPOSITION OF VARIOUS\rFORMERLY-LIVING ENTITIES\rRUMORED TO BE HARASSING\rHONEST CITIZENS IN THE\rVICINITY OF VALHIGEN\rGRAVEYARD. A REWARD IS" },
            { ((short)2, (short)1), "OFFERED TO ANY PERSON WHO\rSHALL TRAVEL TO SAID\rGRAVEYARD AND RETURN AN\rEYE-WITNESS ACCOUNT." },
            { ((short)3, (short)0), "BE IT KNOWN THAT THE\rCOUNCIL IS OFFERING A\rREWARD TO ANY PERSON OR\rPERSONS WHO CAN PROVIDE\rINFORMATION AS TO THE\rDISPOSITION OF SEVERAL\rCOUNCIL AGENTS WHO HAVE\rBEEN SENT TO INVESTIGATE\rTHE UNSEEMLY HAPPENINGS IN" },
            { ((short)3, (short)1), "THE VICINITY OF VALHIGEN\rGRAVEYARD." },
            { ((short)4, (short)0), "BE IT KNOWN THAT THE\rCOUNCIL, KNOWING THAT\rCOMMERCE IS THE LIFE'S\rBLOOD OF NEW PHLAN, HAS\rDECREED THAT SOKAL KEEP IS\rTO BE CLEARED OF ALL\rUNLAWFUL INHABITANTS. A\rREWARD IS OFFERED TO THE\rPERSON OR PERSONS WHO" },
            { ((short)4, (short)1), "SUCCESSFULLY CARRY OUT THIS\rCOMMISSION. ALL INTERESTED\rIN APPLYING FOR SAID\rCOMMISSION SHALL PRESENT\rTHEMSELVES TO THE CLERK OF\rTHE COUNCIL." },
            { ((short)5, (short)0), "BE IT KNOWN THAT THE\rCOUNCIL IS OFFERING AN\rINDUCEMENT TO ANY\rINDIVIDUAL WHO SHALL SERVE\rIN THE RESCUE FORCE FOR THE\rMERCENARY BAND OF\rTAIMALG-THE-INVINCIBLE\rWHICH HAS DISAPPEARED\rINSIDE VALHIGEN GRAVEYARD." },
            { ((short)6, (short)0), "BE IT KNOWN THAT THE\rCOUNCIL IS SEEKING A\rSTALWART BAND TO UNDERTAKE\rA MISSION OF PARTICULAR\rSENSITIVITY. ANY BRAVE AND\rCLEVER BAND OF ADVENTURE\rSEEKERS WHO ARE NOT ADVERSE\rTO EARNING A LARGE REWARD\rSHOULD PRESENT THEMSELVES" },
            { ((short)6, (short)1), "TO THE COUNCIL CLERK FOR A\rSPECIAL COMMISSION." },
            { ((short)7, (short)0), "BE IT KNOWN THAT THE\rCOUNCIL IS OFFERING A\rSPECIAL REWARD FOR THE SAFE\rRETURN OF THE HEIR TO THE\rHOUSE OF BIVANT. SAID MINOR\rWAS CARRIED OFF DURING A\rBUCCANEER ATTACK ON THE\rMERCHANT SHIP IN WHICH HE\rWAS SAILING. APPLY TO THE" },
            { ((short)7, (short)1), "COUNCIL CLERK FOR THE\rCOUNCIL'S COMMISSION AND\rADDITIONAL INFORMATION AS\rTO THE ABDUCTION." },
            { ((short)8, (short)0), "BE IT KNOWN THAT THE\rCOUNCIL HAS DECREED THAT\rTHE THREAT OF THE PIRATES\rWHO PLAGUE EASTERN SHIPPING\rTO NEW PHLAN WILL BE\rELIMINATED. THE COUNCIL\rOFFERS A GENEROUS REWARD\rFOR THE EXACT LOCATION OF\rTHE PIRATES STRONGHOLD IN" },
            { ((short)8, (short)1), "THE TWILIGHT MARSH. AN EVEN\rGREATER REWARD IS OFFERED\rFOR THE ELIMINATION OF THE\rPIRATES AS A THREAT TO\rSHIPPING. APPLY TO THE\rCOUNCIL CLERK FOR A\rCOMMISSION." },
            { ((short)9, (short)0), "BE IT KNOWN THAT THE\rCOUNCIL IS OFFERING A\rREWARD FOR ALL BOOKS AND\rTOMES CONTAINING\rINFORMATION ABOUT THE FALL\rOF PHLAN. THE AMOUNT OF\rSAID REWARD TO BE DEPENDENT\rUPON THE VALUE OF THE\rINFORMATION PROVIDED." },
            { ((short)10, (short)0), "BE IT KNOWN THAT THE\rCOUNCIL HAS DECREED THAT\rTHE FOUL POISONING OF THE\rRIVER FORMERLY KNOWN AS\rSTOJANOW IS TO BE BROUGHT\rTO AN END. ACCORDINGLY, A\rREWARD IS OFFERED TO ANY\rGROUP WHICH SHALL TRAVEL UP\rTHE RIVER CURRENTLY KNOWN" },
            { ((short)10, (short)1), "AS BARREN, LOCATE THE\rSOURCE OF ITS POISONING,\rAND ELIMINATE SAID SOURCE.\rA COMMISSION MAY BE\rOBTAINED FROM THE COUNCIL\rCLERK." },
            { ((short)11, (short)0), "BE IT KNOWN THAT THE\rCOUNCIL HAS DECLARED THOSE\rINDIVIDUALS WHO HAVE TAKEN\rUP RESIDENCE IN THE MANSION\rOF THE FORMER KOVAL FAMILY\rTO BE TRAITORS AND THIEVES.\rBE IT FURTHER KNOWN THAT A\rREWARD HAS BEEN OFFERED FOR\rTHE ELIMINATION OF THESE" },
            { ((short)11, (short)1), "OUTLAWS. A COMMISSION TO\rRID THE CITY OF THIS BLIGHT\rMAY BE OBTAINED FROM THE\rCOUNCIL CLERK." },
            { ((short)12, (short)0), "BE IT KNOWN THAT THE\rCOUNCIL HAS PROCLAIMED A\rGENEROUS BOUNTY FOR EACH\rUNDEAD KILLED. BE IT ALSO\rKNOWN THAT IN ADDITION TO\rSAID BOUNTY, THE COUNCIL IS\rWILLING TO PROVIDE A\rSPECIAL ENCHANTED ITEM,\rUSEFUL IN THE DESTRUCTION" },
            { ((short)12, (short)1), "OF UNDEAD, TO ANY GROUP OF\rADVENTURERS WHICH ACCEPTS\rTHE COMMISSION TO CLEANSE\rVALHIGEN GRAVEYARD. APPLY\rTO THE CITY CLERK FOR SAID\rCOMMISSION." },
            { ((short)13, (short)0), "BE IT KNOWN THAT THE\rCOUNCIL IS SEEKING A HEARTY\rBAND TO UNDERTAKE A MISSION\rTO RESCUE THE DUCHESS OF\rMELVAUNT. THE DUCHESS IS\rSUPPOSEDLY BEING HELD BY A\rBAND OF OGRES IN A CAMP TO\rTHE NORTHEAST OF PHLAN. A\rGENEROUS REWARD IS OFFERED" },
            { ((short)13, (short)1), "FOR THE SAFE RETURN OF THE\rDUCHESS. APPLY TO THE\rCOUNCIL CLERK FOR\rCOMMISSION AND ADDITIONAL\rINFORMATION CONCERNING THE\rABDUCTION." },
            { ((short)14, (short)0), "BE IT KNOWN THAT THE\rCOUNCIL IS INTERESTED IN\rOBTAINING INFORMATION\rCONCERNING BANDS OF INSECT\rMEN KNOWN TO PLAGUE THE\rGRASSY PLANES TO THE WEST\rOF NEW PHLAN. SAID INSECT\rMEN ARE A HAZARD TO\rTRANSPORTATION TO AND FROM" },
            { ((short)14, (short)1), "ZHENTIL KEEP. A REWARD IS\rOFFERED TO ANY PERSON OR\rPERSONS WHO RETURN WITH\rCOMPLETE INFORMATION ON THE\rLOCATION, DISPOSITION, AND\rINTENTIONS OF THE INSECT\rMEN. APPLY TO THE COUNCIL\rCLERK FOR A COMMISSION." },
            { ((short)15, (short)0), "BE IT KNOWN THAT THE\rCOUNCIL IS INTERESTED IN\rOBTAINING INFORMATION ABOUT\rTHE DISPOSITION OF VARIOUS\rHOBGOBLINS BELIEVED TO BE\rGATHERING IN SUPPORT OF\rFORCES BENT UPON THE\rDESTRUCTION OF OUR FAIR\rCITY. A GENEROUS REWARD IS" },
            { ((short)15, (short)1), "OFFERED TO ANY WHO SHALL\rSCOUT OUT THE DOINGS OF\rTHESE FOUL CREATURES AND\rREPORT SUCH TO THE COUNCIL.\rA LARGER REWARD IS OFFERED\rIF THE MARSHALLING OF SAID\rHOBGOBLINS CAN BE\rPREVENTED. A COMMISSION MAY\rBE OBTAINED FROM THE" },
            { ((short)15, (short)2), "COUNCIL CLERK." },
            { ((short)16, (short)0), "BE IT KNOWN THAT THE\rCOUNCIL IS INTERESTED IN\rCLEARING OBSTACLES TO\rESTABLISHING A TRADE ROUTE\rTO THE EAST. SAID OBSTACLES\rCURRENTLY INCLUDE AN\rINFESTATION OF LIZARD MEN\rIN THE SWAMPS TO THE EAST.\rA REWARD IS OFFERED TO ANY" },
            { ((short)16, (short)1), "WHO CAN LOCATE THE SOURCE\rOF THE INFESTATION AND\rREMOVE THE LIZARD MEN AS AN\rOBSTACLE TO TRADE. A\rCOMMISSION MAY BE OBTAINED\rFROM THE COUNCIL CLERK." },
            { ((short)17, (short)0), "BE IT KNOWN THAT THE\rCOUNCIL IS INTERESTED IN\rOBTAINING INFORMATION ABOUT\rTHE DISPOSITION OF VARIOUS\rKOBOLDS CURRENTLY BELIEVED\rTO BE GATHERING IN SUPPORT\rOF FORCES AIMED ON THE\rDESTRUCTION OF OUR FAIR\rCITY. A GENEROUS REWARD IS" },
            { ((short)17, (short)1), "OFFERED TO ANY WHO SHALL\rSCOUT OUT THE DOINGS OF\rTHESE FOUL CREATURES AND\rREPORT SUCH TO THE COUNCIL.\rA LARGER REWARD IS OFFERED\rIF THE MARSHALLING OF SAID\rKOBOLDS CAN BE PREVENTED. A\rCOMMISSION MAY BE OBTAINED\rFROM THE COUNCIL CLERK." },
            { ((short)18, (short)0), "BE IT KNOWN THAT THE\rCOUNCIL IS INTERESTED IN\rOBTAINING INFORMATION ABOUT\rTHE DISPOSITION OF A LARGE\rNOMAD BAND CURRENTLY\rBELIEVED SCOUTING THE\rAPPROACHES TO OUR FAIR\rCITY. A GENEROUS REWARD IS\rOFFERED TO ANY WHO CAN" },
            { ((short)18, (short)1), "PREVENT SAID NOMADS FROM\rJOINING WITH THE FORCE NOW\rGATHERING TO ATTACK NEW\rPHLAN. A COMMISSION MAY BE\rOBTAINED FROM THE COUNCIL\rCLERK." },
            { ((short)19, (short)0), "A LOUD VOICE COMING FROM A\rMAGIC MOUTH CAST ON A STONE\rTABLET.\r\r\"I AM YARASH THE SORCERER!\r\r\"BE KNOWN THAT FOR EVERY\rLIVING GIANT INSECT YOU\rRETURN TO SORCERER'S ISLAND" },
            { ((short)19, (short)1), "I WILL PAY A GENEROUS\rBOUNTY, INCLUDING A WEAPON\rEMPOWERED BY MAGIC. I WILL\rPAY FOR GIANT INSECTS SUCH\rAS THRI-KREEN, GIANT\rMANTIS, AND ANHKHEG. THE\rINSECTS MAY BE BOUND BY\rMAGIC BUT DEAD INSECTS ARE\rOF NO USE TO ME." },
            { ((short)19, (short)2), "\r\"BRING ANY BODIES TO THE\rNORTHERN RIVER MOUTH ON\rLAKE KUTO. CALL THE NAME OF\r\"YARASH\" LOUDLY THREE TIMES\rAND I SHALL COME. DO NOT\rCALL UNLESS YOU HAVE\rSOMETHING FOR ME. I SHALL\rBE VERY ANGRY IF I AM" },
            { ((short)19, (short)3), "DISTURBED WITHOUT CAUSE!\r\r\"I AM YARASH THE SORCERER!\"" },
            { ((short)20, (short)0), "TOLD IN A PAINFUL WHISPER.\r\r\"I NEVER LIKED PAIN. LET ME\rGO AN' I'LL TELL YA OF THE\rKOBOLD TREASURE HORDE. WE\rATTACKED A GOLD SHIPMENT\rONCE -- TOOK IT BY\rSURPRISE. THIRTY TIMES MY\rWEIGHT IN GOLD PIECES WERE" },
            { ((short)20, (short)1), "TAKEN. WE KNEW IF WE WERE\rRAIDED WE'D LOSE THE STUFF\rIN THE TREASURE ROOM. SO WE\rHID IT BEHIND A SECRET DOOR\rIN THE WARRENS -- THAT'S\rWHERE WE KEEP THE\rWOMENFOLK. THEY TOSSED ME\rIN HERE TA DIE, SO IT DON'T\rDO NO HARM TA TELL YE. FIND" },
            { ((short)20, (short)2), "IT AND GOOD RIDDANCE.\"" },
            { ((short)21, (short)0), "AN OLD LEATHER-BOUND BOOK,\rWRITTEN WITH A SMALL, FIRM\rHAND.\r\r\"THE HORDES CAME AGAIN LAST\rNIGHT. THEIR COORDINATION\rWAS FRIGHTENING. UNDER THE\rCOVER OF DARKNESS, GOBLINS\rAND KOBOLDS PUSHED BUNDLES" },
            { ((short)21, (short)1), "OF STICKS TO WITHIN BOW\rRANGE. THESE BUNDLES FORMED\rA WALL THAT PROTECTED THE\rSMALL ONES FROM OUR\rARCHERS. ONCE THE WALL WAS\rERECTED ORC ARCHERS TOOK UP\rSAFE POSITIONS THERE AND\rBEGIN PELTING THE CASTLE\rWALLS WITH ARROWS." },
            { ((short)21, (short)2), "\r\"WE TRIED SHOOTING FLAMING\rARROWS AT THE WALL OF\rSTICKS TO SET IT AFIRE.\rMONSTERS ARE NORMALLY\rAFRAID OF FIRE. BUT THESE\rMONSTERS SHOWED NO FEAR.\rTHEY SIMPLY SCOOPED DIRT ON\rTHE FLAMES TO PUT THEM OUT." },
            { ((short)21, (short)3), "BEFORE ALL THE FIRES WERE\rOUT THEY HAD RESUMED FIRING\rAT US. SURELY, SOME\rUNNATURAL FORCE MUST HAVE\rBEEN AT WORK TO WELD THESE\rQUARLSOME BEASTS INTO AN\rORGANIZED FIGHTING FORCE.\r\r\"I DO NOT KNOW IF WE CAN" },
            { ((short)21, (short)4), "COMBAT THE MONSTERS\rONSLAUGHT MUCH LONGER. WE\rLOST 12 MORE MEN LAST\rNIGHT. THE MONSTERS SEEM TO\rHAVE AN UNLIMITED NUMBER OF\rREINFORCEMENTS. THE LAST\rPRIEST OF TYR, FERRANN\rMARTINEZ, SAYS HE HAS A WAY\rTO PROTECT THE KEEP, BUT HE" },
            { ((short)21, (short)5), "SAYS THAT IT'S SO TERRIBLE\rTHAT IT MAY ONLY BE USED AS\rA LAST RESORT. UNLESS WE\rRECEIVE REINFORCEMENTS\rSHORTLY, FERRAN MARTINEZ IS\rOUR ONLY HOPE.\"" },
            { ((short)22, (short)0), "A ROUGHLY DRAWN CLOTH MAP.\r\r(PICTURE)" },
            { ((short)23, (short)0), "A SMALL PIECE OF PARCHMENT\rFOLDED INTO THE SPINE OF A\rFAMILY'S HOLY BOOK.\r\r\"THE FAMILY TREASURES ARE\rBURIED IN THE TUNNELS\rBENEATH KUTO'S WELL. CLIMB\rDOWN THE WELL AND SEARCH\rFOR A SECRET PASSAGE. IN" },
            { ((short)23, (short)1), "THE PASSAGE THERE IS A\rDANGEROUS TRAP. SEARCH THE\rWALLS UNTIL YOU FIND THE\rLEVER TO DISARM THE TRAP.\rTHEN PROCEED THROUGH THE\rPASSAGE INTO AN ADJACENT\rCHAMBER. THE TREASURES ARE\rBURIED IN THE SOUTHWEST\rCORNER.\"" },
            { ((short)24, (short)0), "A QUICKLY SCRATCHED NOTE.\r\r\"SHOW THE BOSS'S SEAL TO\rTHE THRI-KREEN GUARDS. BE\rCAREFUL, THEY ARE WARY OF\rOUTSIDERS. KEEP YOUR HANDS\rAWAY FROM YOUR WEAPONS NO\rMATTER WHAT THEY DO.\r" },
            { ((short)24, (short)1), "\"WITH THE SEAL YOU SHOULD\rGAIN SAFE PASSAGE IN TO SEE\rTHE QUEEN. SHE WILL GIVE\rYOU THE ARTIFACTS IN\rEXCHANGE FOR THE SEAL AND\rTHE TREATY. DO NOT DO\rANYTHING TO GET HER MAD,\rTHE BUGS WOULD JUST AS SOON\rKILL YOU AS LOOK AT YOU." },
            { ((short)24, (short)2), "ONCE YOU HAVE THE\rARTIFACTS, GET OUT OF THE\rSTINKING BURROW AND GET\rBACK TO THE CASTLE.\"" },
            { ((short)25, (short)0), "A TIGHTLY BOUND SCROLL,\rSEEMINGLY IMMUNE TO THE\rRAVAGES OF TIME.\r\r\"FOUNTAINS AND POOLS HOLD\rGREAT POWER THAT CAN ONLY\rBE REACHED BY PERFORMING\rPROPER CEREMONIES. MOST\rSURE OF THESE IS IMMERSION," },
            { ((short)25, (short)1), "FOR IN THIS WAY THE BATHER\rSURRENDERS HIMSELF TO THE\rSPIRIT OF THE WATER. THAT\rSPIRIT, OR SOME PORTION OF\rIT, ENTERS INTO THE BATHER,\rWHEREBY HE GAINS GREAT\rPOWERS. WOE TO THE WEAK\rWILLED WHOSE SPIRITS ARE\rSURE TO BE CONSUMED BY" },
            { ((short)25, (short)2), "SPIRITS THAT PUT EVEN THE\rSTRONG AT GREAT RISK. YURAX\rHOLDS THAT THE FALLS OF\rIXCE ARE GREATEST OF ALL\rTHESE. MORDEN WRITES THAT\rTHE POOL OF RADIANCE IS\rGREATER STILL.\"\r\rLATER IN THE BOOK," },
            { ((short)25, (short)3), "\r\"PLACES OF MAGICAL POWER\rARE NOT NECESSARILY TIED TO\rONE PHYSICAL LOCATION.\rPOWER OFTEN MOVES FROM\rPLANE TO PLANE ALONG THE\rPATH OF LEAST RESISTANCE.\rTHE TERMINATION OF THE PATH\rDETERMINES THE PLACE'S" },
            { ((short)25, (short)4), "LOCATION ON THIS PLANE.\rVOLATILE UPHEAVALS BETWEEN\rTHE PLANES MAY LEAD TO A\rCHANGE IN THE PATH OF LEAST\rRESISTANCE. THIS CAN CHANGE\rWHERE THE PATH TERMINATES\rON THIS PLANE, THUS MOVING\rTHE PLACE OF POWER.\r" },
            { ((short)25, (short)5), "(PICTURE: LEGEND FOR ALL\rMAPS)\r\r\"SOME WHO WIELD STRONG\rSUPERNATURAL FORCES CAN\rBEND THE PATH LIKE AN\rENGINEER DAMMING A RIVER.\rWHEN THE PATH IS BENT, IT\rCAN TERMINATE IN A NEW" },
            { ((short)25, (short)6), "LOCATION, MOVING THE PLACE\rOF POWER ON THIS PLANE. IF\rTHE SUPERNATURAL FORCE THAT\rBENT THE PATH IS REMOVED,\rTHE PATH WILL SNAP BACK TO\rITS ORIGINAL FORM AND THE\rPLACE OF POWER WILL RETURN\rTO ITS ORIGINAL LOCATION.\rSUCH DISRUPTION CAN HAVE" },
            { ((short)25, (short)7), "VIOLENT AND UNPREDICTABLE\rRESULTS.\r\r\"THUS, INTER-PLANAR\rUPHEAVALS AND DIRECTED\rSUPERNATURAL FORCES MAY\rHOLD THE ANSWER TO THE\rSEEMINGLY EVER-CHANGING\rLOCATION OF PLACES OF" },
            { ((short)25, (short)8), "POWER, SUCH AS THE POOL OF\rRADIANCE.\"" },
            { ((short)26, (short)0), "A RUGGED POPULAR ACCOUNT OF\rTHE NORTHERN LANDS.\r\r\"TEN DAYS RIDE NORTH OF THE\rVARM IS A BARREN AND DEAD\rCOUNTRY CALLED THE LEEWAI,\rLAND-IN-PAIN OR\rLAND-OF-CAUSED-PAIN.\rFURTHER TO THE SOUTH THIS" },
            { ((short)26, (short)1), "PLACE IS KNOWN AS THE\rTORTURED LAND. IT IS SAID\rTO BE AN EVIL PLACE,\rSHUNNED BY THE RIDERS. THEY\rSPEAK LITTLE OF THIS LAND.\rBUT, YEARLY, DURING CHES,\rTHEY MAKE A TRIP INTO ITS\rHEART. THERE THEY GO TO\rPRAISE THE SPIRIT OF A" },
            { ((short)26, (short)2), "GLOWING SPRING. THIS THEY\rHAVE DONE FOR AGES AND SO\rSHALL THEY DO FOR YEARS TO\rCOME.\"" },
            { ((short)27, (short)0), "SEVERAL PIECES OF PAPER\rWITH HIGHLY ORGANIZED\rWRITING.\r\rFACT: JORAN ALBERACH IS A\rSPECIAL ENVOY, FROM ZHENTIL\rKEEP, TO THE CITY COUNCIL\rOF NEW PHLAN.\r" },
            { ((short)27, (short)1), "STRONG RUMOR: HERE TO\rNEGOTIATE A MILITARY\rASSISTANCE AGREEMENT\rBETWEEN ZHENTIL KEEP AND\rNEW PHLAN.\r\rRUMOR: ZHENTIL KEEP WANTS\rAN ANCIENT POWERFUL\rARTIFACT IN RETURN FOR" },
            { ((short)27, (short)2), "THEIR MILITARY COOPERATION.\r\rRUMOR: THE NEW PHLAN CITY\rCOUNCIL HAS SUCH AN\rARTIFACT THAT WAS FOUND IN\rTHE RUINS OF A RECENTLY\rRECLAIMED BUILDING.\r\rVAGUE RUMOR: JORAN ALBERACH" },
            { ((short)27, (short)3), "WANTS THE ARTIFACT FOR\rHIMSELF, NOT FOR THE RULERS\rOF ZHENTIL KEEP." },
            { ((short)28, (short)0), "A CRUDE MAP SCRATCHED ONTO\rAN OLD PIECE OF PARCHMENT.\r\r(PICTURE)" },
        };

        public static short LineCount(short index)
        {
            short result;
            return LineCounts.TryGetValue(index, out result) ? result : (short)0;
        }

        public static string TextChunk(short index, short chunk)
        {
            string result;
            return Chunks.TryGetValue((index, chunk), out result) ? result : string.Empty;
        }
    }
}